import{_ as a,a0 as g,w as d,s as u,ao as n,I as t,x as o,a1 as i,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"教你用 google-drive-ocamlfuse 在 Linux 上掛載 Google Drive | LCTT x X-CMD","titleTemplate":false,"description":"教你用 google-drive-ocamlfuse 在 Linux 上掛載 Google Drive | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"教你用 google-drive-ocamlfuse 在 Linux 上掛載 Google Drive | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"教你用 google-drive-ocamlfuse 在 Linux 上掛載 Google Drive | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160602 How to mount your Google Drive on Linux with google-drive-ocamlfuse","title":"教你用 google-drive-ocamlfuse 在 Linux 上掛載 Google Drive","tag":"201607","desc":""},"relativePath":"201607/20160602 How to mount your Google Drive on Linux with google-drive-ocamlfuse.md","filePath":"[post].md"}'),s={name:"201607/20160602 How to mount your Google Drive on Linux with google-drive-ocamlfuse.md"};function p(m,e,v,c,f,h){const l=g("Link");return d(),u("div",null,[e[13]||(e[13]=n('<h1 id="教你用-google-drive-ocamlfuse-在-linux-上掛載-google-drive" tabindex="-1">教你用 google-drive-ocamlfuse 在 Linux 上掛載 Google Drive <a class="header-anchor" href="#教你用-google-drive-ocamlfuse-在-linux-上掛載-google-drive" aria-label="Permalink to “教你用 google-drive-ocamlfuse 在 Linux 上掛載 Google Drive”">​</a></h1><blockquote><p>如果你在找一個方便的方式在 Linux 機器上掛載你的 Google Drive 文件夾， Jack Wallen 將教你怎麼使用 google-drive-ocamlfuse 來掛載 Google Drive。</p></blockquote><p><img src="http://tr4.cbsistatic.com/hub/i/2016/05/18/ee5d7b81-e5be-4b24-843d-d3ca99230a63/651be96ac8714698f8100afa6883e64d/linuxcloudhero.jpg" alt=""></p><p><em>圖片來源: Jack Wallen</em></p><p>Google 還沒有發行 Linux 版本的 Google Drive 應用，儘管現在有很多方法從 Linux 中訪問你的 Drive 文件。</p><p>如果你喜歡界面化的工具，你可以選擇 Insync。如果你喜歡用命令列，有很多像 Grive2 這樣的工具，和更容易使用的以 Ocaml 語言編寫的基於 FUSE 的文件系統。我將會用後面這種方式演示如何在 Linux 桌面上掛載你的 Google Drive。儘管這是通過命令列完成的，但是它的用法會簡單到讓你吃驚。它太簡單了以至於誰都能做到。</p><p>這個系統的特點：</p><ul><li>對普通文件/文件夾有完全的讀寫權限</li><li>對於 Google Docs，sheets，slides 這三個應用只讀</li><li>能夠訪問 Drive 回收站（.trash）</li><li>處理重複文件功能</li><li>支持多個帳號</li></ul><p>讓我們接下來完成 google-drive-ocamlfuse 在 Ubuntu 16.04 桌面的安裝，然後你就能夠訪問雲盤上的文件了。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><ol><li>打開終端。</li><li>用 <code>sudo add-apt-repository ppa:alessandro-strada/ppa</code> 命令添加必要的 PPA</li><li>出現提示的時候，輸入你的 root 密碼並按下回車。</li><li>用 <code>sudo apt-get update</code> 命令更新應用。</li><li>輸入 <code>sudo apt-get install google-drive-ocamlfuse</code> 命令安裝軟件。</li></ol><h3 id="授權" tabindex="-1">授權 <a class="header-anchor" href="#授權" aria-label="Permalink to “授權”">​</a></h3><p>接下來就是授權 google-drive-ocamlfuse，讓它有權限訪問你的 Google 賬户。先回到終端窗口敲下命令 <code>google-drive-ocamlfuse</code>，這個命令將會打開一個瀏覽器窗口，它會提示你登陸你的 Google 帳號或者如果你已經登陸了 Google 帳號，它會詢問是否允許 google-drive-ocamlfuse 訪問 Google 賬户。如果你還沒有登錄，先登錄然後點擊“允許”。接下來的窗口（在 Ubuntu 16.04 桌面上會出現，但不會出現在 Elementary OS Freya 桌面上）將會詢問你是否授給 gdfuse 和 OAuth2 Endpoint 訪問你的 Google 賬户的權限，再次點擊“允許”。然後出現的窗口就會告訴你等待授權令牌下載完成，這個時候就能最小化瀏覽器了。當你的終端提示如下圖一樣的內容，你就能知道令牌下載完了，並且你已經可以掛載 Google Drive 了。</p><p><img src="http://tr4.cbsistatic.com/hub/i/r/2016/05/18/a493122b-445f-4aca-8974-5ec41192eede/resize/620x/6ae5907ad2c08dc7620b7afaaa9e389c/googledriveocamlfuse3.png" alt=""></p><p><em>應用已經得到授權，你可以進行後面的工作。</em></p><h3 id="掛載-google-drive" tabindex="-1">掛載 Google Drive <a class="header-anchor" href="#掛載-google-drive" aria-label="Permalink to “掛載 Google Drive”">​</a></h3><p>在掛載 Google Drive 之前，你得先創建一個文件夾，作為掛載點。在終端裏，敲下<code>mkdir ~/google-drive</code>命令在你的家目錄下創建一個新的文件夾。最後敲下命令<code>google-drive-ocamlfuse ~/google-drive</code>將你的 Google Drive 掛載到 google-drive 文件夾中。</p><p>這時你可以查看本地 google-drive 文件夾中包含的 Google Drive 文件/文件夾。你可以把 Google Drive 當作本地文件系統來進行工作。</p><p>當你想卸載 google-drive 文件夾，輸入命令 <code>fusermount -u ~/google-drive</code>。</p><h3 id="沒有-gui-但它特別好用" tabindex="-1">沒有 GUI，但它特別好用 <a class="header-anchor" href="#沒有-gui-但它特別好用" aria-label="Permalink to “沒有 GUI，但它特別好用”">​</a></h3><p>我發現這個特別的系統非常容易使用，在同步 Google Drive 時它出奇的快，並且這可以作為一種本地備份你的 Google Drive 賬户的巧妙方式。（LCTT 譯註：然而首先你得能使用……）</p><p>試試 google-drive-ocamlfuse，看看你能用它做出什麼有趣的事。</p><hr>',23)),t("p",null,[e[1]||(e[1]=o("via: ",-1)),i(l,{href:"http://www.techrepublic.com/article/how-to-mount-your-google-drive-on-linux-with-google-drive-ocamlfuse/"},{default:r(()=>[...e[0]||(e[0]=[o("http://www.techrepublic.com/article/how-to-mount-your-google-drive-on-linux-with-google-drive-ocamlfuse/",-1)])]),_:1})]),t("p",null,[e[5]||(e[5]=o("作者：",-1)),i(l,{href:"http://www.techrepublic.com/search/?a=jack+wallen"},{default:r(()=>[...e[2]||(e[2]=[o("Jack Wallen",-1)])]),_:1}),e[6]||(e[6]=o(" 譯者：",-1)),i(l,{href:"https://github.com/GitFuture"},{default:r(()=>[...e[3]||(e[3]=[o("GitFuture",-1)])]),_:1}),e[7]||(e[7]=o(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[10]||(e[10]=o("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原創編譯，",-1)),i(l,{href:"https://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[o("Linux中國",-1)])]),_:1}),e[12]||(e[12]=o(" 榮譽推出",-1))])])}const b=a(s,[["render",p]]);export{D as __pageData,b as default};
